A closure is a function that has access to its outer function's scope even after the outer function has returned:

```javascript
function outer() {
    let count = 0;
    return function inner() {
        count++;
        return count;
    };
}

const counter = outer();
console.log(counter()); // 1
console.log(counter()); // 2
```

Closures are useful for data encapsulation and creating private variables.

React Hooks are functions that let you use state and other React features in functional components:

```jsx
import React, { useState, useEffect } from 'react';

function Example() {
    const [count, setCount] = useState(0);

    useEffect(() => {
        document.title = `Count: ${count}`;
    }, [count]);

    return (
        <div>
            <p>You clicked {count} times</p>
            <button onClick={() => setCount(count + 1)}>
                Click me
            </button>
        </div>
    );
}
```

Async/await makes asynchronous code easier to write and read:

```javascript
// Using async/await
async function fetchData() {
    try {
        const response = await fetch('api/data');
        const data = await response.json();
        return data;
    } catch (error) {
        console.error('Error:', error);
    }
}

// Equivalent to promises
function fetchData() {
    return fetch('api/data')
        .then(response => response.json())
        .catch(error => console.error('Error:', error));
}
```

